from pathlib import Path
import os,json,base64,hashlib,subprocess
root=Path('/home/orangepi/drone_platform')
cfg={'path': '01_apps/ego_planner/record_session.py', 'expected_old_sha256': '1b512f94687e2c7bd5d4e6d4b3a32c9aea2e9cb2edf8067ee3836b66e134b4fa', 'expected_head': 'bfc044a3b0a82bca28b539dd733722dfee286d2e', 'new_sha256': '48519ba7b654812584bc4aad3703db1118506f523763d5def3891be2a639f2b3', 'base64': ''}
def git(*args):return subprocess.check_output(['git','-C',str(root),*args]).decode().strip()
assert git('rev-parse','HEAD')==cfg['expected_head']
assert not git('status','--porcelain')
target=root/cfg['path'];old=target.read_bytes();new=base64.b64decode(cfg['base64'])
assert hashlib.sha256(old).hexdigest()==cfg['expected_old_sha256']
assert hashlib.sha256(new).hexdigest()==cfg['new_sha256']
# 本次仅部署停用中的源码，不停止或重启服务。
assert subprocess.run(['pgrep','-f',str(root)+'/01_apps/ego_planner/record_session.py'],capture_output=True).returncode==1
compile(new,str(target),'exec')
staging=target.with_name(target.name+'.candidate-tmp')
assert not staging.exists()
staging.write_bytes(new);os.chmod(staging,target.stat().st_mode & 0o777);os.replace(staging,target)
subprocess.run(['git','-C',str(root),'add','--',cfg['path']],check=True)
subprocess.run(['git','-C',str(root),'-c','user.name=tyzk','-c','user.email=940833041@qq.com','commit','-m','Restore default rosbag2 discovery polling interval'],check=True)
print(json.dumps({'head':git('rev-parse','HEAD'),'path':cfg['path'],'old_sha256':cfg['expected_old_sha256'],'new_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'git_clean':not git('status','--porcelain'),'services_changed':False},indent=2))
